   325	void NcpBase::HandleReceive(const uint8_t *aBuf, uint16_t aBufLength)
   326	{
   327	    otError      error  = OT_ERROR_NONE;
   328	    uint8_t      header = 0;
   329	    spinel_tid_t tid    = 0;
   330	
   331	    mDisableStreamWrite = true;
   332	
   333	    // Initialize the decoder with the newly received spinel frame.
   334	    mDecoder.Init(aBuf, aBufLength);
   335	
   336	    // Receiving any message from the host has the side effect of transitioning the host power state to online.
   337	    mHostPowerState           = SPINEL_HOST_POWER_STATE_ONLINE;
   338	    mHostPowerStateInProgress = false;
   339	
   340	    // Skip if there is no header byte to read or this isn't a spinel frame.
   341	
   342	    SuccessOrExit(mDecoder.ReadUint8(header));
   343	    VerifyOrExit((SPINEL_HEADER_FLAG & header) == SPINEL_HEADER_FLAG);
   344	
   345	    mRxSpinelFrameCounter++;
   346	
   347	    // We only support IID zero for now.
   348	    if (SPINEL_HEADER_GET_IID(header) != 0)
   349	    {
   350	        WriteLastStatusFrame(header, SPINEL_STATUS_INVALID_INTERFACE);
   351	        ExitNow();
   352	    }
   353	
   354	    error = HandleCommand(header);
   355	
   356	    if (error != OT_ERROR_NONE)
   357	    {
   358	        PrepareLastStatusResponse(header, ThreadErrorToSpinelStatus(error));
   359	    }
   360	
   361	    if (!IsResponseQueueEmpty())
   362	    {
   363	        // A response may have been prepared and queued for this command,
   364	        // so we attempt to send/write any queued responses. Note that
   365	        // if the response was prepared but cannot be sent now (not
   366	        // enough buffer space available), it will be attempted again
   367	        // from `HandleFrameRemovedFromNcpBuffer()` when buffer space
   368	        // becomes available.
   369	
   370	        IgnoreReturnValue(SendQueuedResponses());
   371	    }
   372	
   373	    // Check for out of sequence TIDs and update `mNextExpectedTid`,
   374	
   375	    tid = SPINEL_HEADER_GET_TID(header);
   376	
   377	    if ((mNextExpectedTid != 0) && (tid != mNextExpectedTid))
   378	    {
   379	        mRxSpinelOutOfOrderTidCounter++;
   380	    }
   381	
   382	    mNextExpectedTid = SPINEL_GET_NEXT_TID(tid);
   383	
   384	exit:
   385	    mDisableStreamWrite = false;
   386	}
