   399	void NcpBase::HandleFrameRemovedFromNcpBuffer(NcpFrameBuffer::FrameTag aFrameTag)
   400	{
   401	    if (mHostPowerStateInProgress)
   402	    {
   403	        if (aFrameTag == mHostPowerReplyFrameTag)
   404	        {
   405	            mHostPowerStateInProgress = false;
   406	        }
   407	    }
   408	
   409	    // A frame was removed from NCP TX buffer, so more space is now available.
   410	    // We attempt to write/send any pending frames. Order of the checks
   411	    // below is important: First any queued command responses, then
   412	    // any queued IPv6 datagram messages, then any asynchronous property updates.
   413	    // If a frame still can not fit in the available buffer, we exit immediately
   414	    // and wait for next time this callback is invoked (when another frame is
   415	    // removed and more buffer space becomes available).
